    (1, '3659016341', '1533', '2019-10-18', 5912.36, 'GTQ', 1, 'BYRON OSWALDO ACEVEDO BARRIOS***** ANULADO****', null, 'ANULADO', 'AEV', null, null, false, 'M', 'I', null, null, null, 1, 1, 'GUATEMALA', null, null, null, 1021, 'N', '2019-10-18 00:00:00', false, false, null, null, null, '000000001533', false, 5912.36, '3659016341')) as x(loc, cuenta, numero, fecha, valor, moneda, cambio, beneficiario, descripcion, estado, usuario, f_anula, proveedor, procesado, tipo_ant,
      conciliado, f_concilia, motivo_cod, motivo, moneda_int, cambio_ant, lugar, postfechado, usr_mod, f_mod, transaccion, negociable, f_ingreso, firmado,
      obviar, obs_anula, valor_mi, tipo_rubro, doc_mig, cxc, valor_ant, cuenta_ant)
    order by loc, fecha, numero loop
    select id into v_loc from public.localidades where organizacion_id = v_org and correlativo = r.loc;
    select cb.id, cb.moneda_id into v_cb from public.cuentas_bancarias cb where cb.localidad_id = v_loc and cb.numero = r.cuenta;
    if v_cb.id is null then c_s := c_s + 1; raise notice 'Cheque % (3-0%): no existe la cuenta bancaria %.', r.numero, r.loc, r.cuenta; continue; end if;
    select id into v_id from public.movimientos_bancarios where tipo = 'CHEQUE' and cuenta_bancaria_id = v_cb.id and numero_documento = r.numero;
    select nombre_comercial into v_prov from public.proveedores where localidad_id = v_loc and codigo = r.proveedor::integer;
    select id into v_tr from public.transacciones_contables where localidad_id = v_loc and numero = r.transaccion::integer;
    if v_id is null then
      select coalesce(max(folio), 0) + 1 into v_folio from public.movimientos_bancarios where localidad_id = v_loc and tipo = 'CHEQUE';
